import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/constants.dart';
import '../../../core/providers.dart';
import '../../../core/widgets/common.dart';
import '../../../core/theme/app_theme.dart';
import '../../billing/domain/billing_calculator.dart';

class SlipsScreen extends ConsumerWidget{const SlipsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final slips=ref.watch(slipsProvider).asData?.value??const <Map<String,dynamic>>[];final challans=ref.watch(challansProvider).asData?.value??const <Map<String,dynamic>>[];return DefaultTabController(length:2,child:Scaffold(appBar:AppBar(title:const Text('Material documents'),bottom:const TabBar(tabs:[Tab(text:'Delivery / Return'),Tab(text:'Challans')])),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_newSlip(context,ref),icon:const Icon(Icons.add),label:const Text('New document')),body:TabBarView(children:[_list(slips,'slip_no',context),_list(challans,'challan_no',context)])));}}
Widget _list(List<Map<String,dynamic>> rows,String key,BuildContext context)=>rows.isEmpty?const EmptyState(title:'No documents yet',description:'Create delivery slips, return slips, or challans.'):ListView.separated(padding:const EdgeInsets.all(16),itemCount:rows.length,itemBuilder:(c,i){final r=rows[i];return Card(child:ListTile(leading:CircleAvatar(backgroundColor:AppPalette.of(context).subtle,child:Icon('${r['type']}'.contains('RETURN')?Icons.assignment_return_outlined:Icons.local_shipping_outlined,color:AppPalette.of(context).accent)),title:Text('${r[key]} · ${r['type']}',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('${displayDate(r['date'])} · ${r['customer_name']??'Material movement'}'),trailing:TextButton(onPressed:()=>_showDocument(c,r),child:const Text('View'))));},separatorBuilder:(_,__)=>const SizedBox(height:8));
void _showDocument(BuildContext context,Map<String,dynamic> row)=>showModalBottomSheet(context:context,isScrollControlled:true,builder:(c)=>SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:ListView(shrinkWrap:true,children:[Text('${row['type']} · ${row['slip_no']??row['challan_no']}',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text('Date ${displayDate(row['date'])} · ${row['customer_name']??''} · ${row['mobile']??''}'),const SectionTitle('Materials'),...materialCatalog.map((s)=>Text('${s.label}: ${(row['items'] as Map? ?? {})[s.key]??0}')),const SectionTitle('Wood'),...woodCatalog.map((s)=>Text('${s.label}: ${woodToText(parseWoodSizes((row['wood'] as Map? ?? {})[s.key]))}')),if('${row['note']??''}'.isNotEmpty)Text('Note: ${row['note']}')]))));
Future<void> _newSlip(BuildContext context,WidgetRef ref)async{final choice=await showModalBottomSheet<String>(context:context,builder:(c)=>SafeArea(child:Wrap(children:[for(final x in ['DELIVERY','RETURN','CHALLAN'])ListTile(title:Text(x),leading:Icon(x=='RETURN'?Icons.assignment_return_outlined:x=='CHALLAN'?Icons.description_outlined:Icons.local_shipping_outlined),onTap:()=>Navigator.pop(c,x))])));if(choice==null)return;if(context.mounted)await Navigator.push(context,MaterialPageRoute(builder:(_)=>_DocumentForm(type:choice)));}
class _DocumentForm extends ConsumerStatefulWidget{const _DocumentForm({required this.type});final String type;@override ConsumerState<_DocumentForm> createState()=>_DocumentFormState();}
class _DocumentFormState extends ConsumerState<_DocumentForm>{final c=<String,TextEditingController>{};bool saving=false;@override void initState(){super.initState();for(final k in ['customer_name','mobile','place','vehicle_no','driver_name','trip_no','note','date',...materialCatalog.map((s)=>'qty_${s.key}'),...woodCatalog.map((s)=>s.key)]){c[k]=TextEditingController(text:k=='date'?dateKey(DateTime.now()):k=='trip_no'?'1':k.startsWith('qty_')?'0':'');}}
@override void dispose(){for(final x in c.values)x.dispose();super.dispose();}
Widget f(String k,String label,{bool numeric=false,String? hint})=>Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:c[k],keyboardType:numeric?TextInputType.number:TextInputType.text,decoration:InputDecoration(labelText:label,hintText:hint)));
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('New ${widget.type.toLowerCase()}')),body:ListView(padding:const EdgeInsets.all(18),children:[OutlinedButton.icon(onPressed:() async {final current=DateTime.tryParse(c['date']!.text)??DateTime.now();final picked=await showDatePicker(context:context,initialDate:current,firstDate:DateTime(2000),lastDate:DateTime(2100));if(picked!=null)setState(()=>c['date']!.text=dateKey(picked));},icon:const Icon(Icons.calendar_today_outlined),label:Text('Date · ${displayDate(c['date']!.text)}')),f('customer_name','Customer name'),f('mobile','Mobile'),f('place','Place'),if(widget.type!='CHALLAN')... [f('trip_no','Trip number',numeric:true),f('vehicle_no','Vehicle number'),f('driver_name','Driver name')],const SectionTitle('Material quantities'),...materialCatalog.map((s)=>f('qty_${s.key}',s.label,numeric:true)),const SectionTitle('Wood pieces'),...woodCatalog.map((s)=>f(s.key,s.label,hint:'8×5+10×2')),f('note','Note'),FilledButton.icon(onPressed:saving?null:save,icon:const Icon(Icons.save_outlined),label:Text(saving?'Saving…':'Save ${widget.type.toLowerCase()}'))]));
Future<void> save()async{setState(()=>saving=true);try{final repo=ref.read(billingRepositoryProvider);final isChallan=widget.type=='CHALLAN';final now=DateTime.now().toUtc().toIso8601String();final items={for(final s in materialCatalog)s.key:(int.tryParse(c['qty_${s.key}']!.text)??0).clamp(0,100000000)};final wood={for(final s in woodCatalog)s.key:c[s.key]!.text.trim()};if(isChallan){final seq=await repo.nextSequence('challan_seq');await repo.put('challans',{'challan_no':'SACH-${seq.toString().padLeft(5,'0')}','type':'DELIVERY','date':c['date']!.text,'note':c['note']!.text.trim(),'items':items,'wood':wood,'created_at':now,'created_by':ref.read(authRepositoryProvider).currentUser?.email??''});}else{final isReturn=widget.type=='RETURN';final seq=await repo.nextSequence(isReturn?'return_slip_seq':'delivery_slip_seq');final prefix=isReturn?'SART':'SADL';await repo.put('slips',{'slip_no':'$prefix-${seq.toString().padLeft(5,'0')}','type':widget.type,'date':c['date']!.text,'customer_name':c['customer_name']!.text.trim(),'mobile':c['mobile']!.text.trim(),'place':c['place']!.text.trim(),'trip_no':int.tryParse(c['trip_no']!.text)??1,'vehicle_no':c['vehicle_no']!.text.trim(),'driver_name':c['driver_name']!.text.trim(),'note':c['note']!.text.trim(),'items':items,'wood':wood,'created_at':now,'created_by':ref.read(authRepositoryProvider).currentUser?.email??''});}if(mounted)Navigator.pop(context);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Save failed: $e')));}finally{if(mounted)setState(()=>saving=false);}}
}
